  insert into public.placement_groups (section_id, title, passage, sort_order) values (sid, $q$Local Library to Host Free Reading Festival$q$, $q$The Greenfield Community Library will host its first Reading Festival next month, running from the 14th to the 16th. Organisers say the event aims to encourage more young people to read for pleasure, especially after research showed a drop in reading habits among teenagers in the area. The festival will include author talks, book swaps, and workshops for children. Entry is free, but visitors are asked to register online in advance, as spaces are limited. Local schools have already booked group visits for the first day, so families hoping to attend the opening day are advised to arrive early or consider visiting on the second or third day instead.$q$, 1) returning id into gid;
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$Why did the library decide to organise the festival?$q$, $q$["To raise money for new books", "Because reading among teenagers has decreased", "To celebrate its anniversary", "Because a new library was built"]$q$::jsonb, 1, 1, 'mcq', 1);
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$How long does the festival last?$q$, $q$["One day", "Two days", "Three days", "A week"]$q$::jsonb, 2, 1, 'mcq', 2);
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$What must visitors do before attending?$q$, $q$["Pay an entry fee", "Bring a book to swap", "Register online", "Book through their school"]$q$::jsonb, 2, 1, 'mcq', 3);
