  insert into public.placement_sections (test_id, title, skill, time_min, scoring, instructions, sort_order) values (tid, $q$Section 5 — Questions 19–24 (Opinion Article)$q$, 'reading', 10, 'auto', $q$[]$q$::jsonb, 6) returning id into sid;
  insert into public.placement_groups (section_id, title, passage, sort_order) values (sid, $q$The Remote Work Debate$q$, $q$Five years after the pandemic forced millions of employees to work from home, companies remain divided over whether remote work benefits or harms productivity. Proponents argue that flexible working arrangements boost morale, reduce commuting time, and allow companies to recruit talent regardless of geographic location. Critics, however, point to a decline in spontaneous collaboration and worry that younger employees, in particular, miss out on the informal mentorship that often occurs in a physical office. Some organisations have attempted a middle ground, requiring staff to attend the office two or three days a week, though this hybrid model has its own critics, who argue it combines the drawbacks of both systems without fully delivering the benefits of either. What is increasingly clear is that a one-size-fits-all policy is unlikely to satisfy every industry, role, or individual, and that the debate is far from settled.$q$, 1) returning id into gid;
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$According to the passage, what is one advantage of remote work mentioned by its supporters?$q$, $q$["Increased office space", "Reduced commuting time", "Higher salaries", "Less need for training"]$q$::jsonb, 1, 1, 'mcq', 1);
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$What concern do critics of remote work raise?$q$, $q$["It increases costs for companies", "It reduces spontaneous collaboration", "It requires more office space", "It leads to higher staff turnover"]$q$::jsonb, 1, 1, 'mcq', 2);
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$Who, according to critics, may be particularly disadvantaged by remote work?$q$, $q$["Senior managers", "Younger employees", "Freelancers", "Part-time staff"]$q$::jsonb, 1, 1, 'mcq', 3);
