  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$What criticism is made of the hybrid model?$q$, $q$["It is too expensive", "It combines the disadvantages of both systems", "It is illegal in some countries", "It only suits large companies"]$q$::jsonb, 1, 1, 'mcq', 5);
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$What is the overall tone of the passage's conclusion?$q$, $q$["Strongly in favour of remote work", "Strongly against remote work", "Suggesting no single policy fits everyone", "Predicting remote work will disappear soon"]$q$::jsonb, 2, 1, 'mcq', 6);
  insert into public.placement_sections (test_id, title, skill, time_min, scoring, instructions, sort_order) values (tid, $q$Section 6 — Questions 25–28 (Academic Text)$q$, 'reading', 10, 'auto', $q$[]$q$::jsonb, 7) returning id into sid;
  insert into public.placement_groups (section_id, title, passage, sort_order) values (sid, $q$The Paradox of Choice Revisited$q$, $q$It has become something of a truism in behavioural economics that more choice does not necessarily equate to greater satisfaction. Barry Schwartz's influential thesis, popularised in the early 2000s, argued that an abundance of options can lead to decision paralysis and, paradoxically, diminished contentment with whatever is eventually chosen. Yet recent research complicates this picture considerably. A meta-analysis spanning several decades of choice-related studies found that the negative effects of choice overload are far from universal, emerging reliably only under specific conditions: when options are difficult to compare, when the decision carries significant stakes, and when the chooser lacks clear prior preferences. In contexts where these conditions are absent, additional choice can in fact enhance satisfaction, as consumers value the sense of autonomy that a wider selection affords. This nuance is often lost in popular retellings of the original thesis, which tend to flatten a conditional finding into a universal law.$q$, 1) returning id into gid;
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$According to the passage, what was Barry Schwartz's original argument?$q$, $q$["People always prefer more choices", "Too many choices can reduce satisfaction", "Choice has no effect on satisfaction", "Choice overload only affects experts"]$q$::jsonb, 1, 1, 'mcq', 1);
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$What does the recent meta-analysis suggest about choice overload?$q$, $q$["It affects everyone equally", "It only occurs under certain conditions", "It has been completely disproven", "It only applies to online shopping"]$q$::jsonb, 1, 1, 'mcq', 2);
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$Under which condition is choice overload NOT likely to occur, according to the passage?$q$, $q$["When options are hard to compare", "When the decision has high stakes", "When the chooser already has clear preferences", "When the chooser is inexperienced"]$q$::jsonb, 2, 1, 'mcq', 3);
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$What criticism does the author make of "popular retellings" of Schwartz's thesis?$q$, $q$["They ignore the original research entirely", "They oversimplify a conditional finding into an absolute rule", "They exaggerate the benefits of choice", "They focus only on consumer products"]$q$::jsonb, 1, 1, 'mcq', 4);
  insert into public.placement_sections (test_id, title, skill, time_min, scoring, instructions, sort_order) values (tid, $q$Section 7 — Questions 29–30 (Abstract Text)$q$, 'reading', 10, 'auto', $q$[]$q$::jsonb, 8) returning id into sid;
  insert into public.placement_groups (section_id, title, passage, sort_order) values (sid, $q$On the Instability of Meaning$q$, $q$Language, for all its apparent stability, is a system perpetually on the verge of destabilisation. Every utterance is haunted by the specific echoes of its previous usages, such that no word arrives at the listener wholly innocent of its history. This is not merely a matter of connotation accruing over time, as a dictionary definition might suggest, but something more fundamentally unsettling: the very possibility of a word meaning precisely what its user intends is perpetually deferred, contingent upon a shared context that can never be fully secured between speaker and listener. To communicate, then, is not to transmit a fixed meaning but to gamble on an approximate convergence of interpretation, one that succeeds often enough to sustain the illusion of linguistic stability.$q$, 1) returning id into gid;
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$What is the author's central claim about language?$q$, $q$["Words have fixed, stable meanings over time", "Meaning is never fully secured and depends on shared context", "Dictionaries accurately capture all word meanings", "Communication always fails between speakers"]$q$::jsonb, 1, 1, 'mcq', 1);
  insert into public.placement_questions (test_id, section, section_id, group_id, context, prompt, options, correct_index, points, qtype, sort_order) values (tid, 'reading', sid, gid, null, $q$What does the author mean by "the illusion of linguistic stability"?$q$, $q$["Language is truly stable and unchanging", "The impression of stable meaning masks an underlying uncertainty", "Illusions are common in poetic language only", "Stability is achieved only in written language"]$q$::jsonb, 1, 1, 'mcq', 2);
